import base64
import json
import pickle


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing serialized user preferences

    Returns:
        A dictionary containing the user's preference settings
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # Try JSON first (secure), fallback to pickle for legacy compatibility
        try:
            preferences = json.loads(decoded_data)
        except (json.JSONDecodeError, UnicodeDecodeError):
            preferences = pickle.loads(decoded_data)

        # Ensure the deserialized data is a dictionary
        if not isinstance(preferences, dict):
            return {}

        return preferences
    except Exception:
        # Fail securely: return empty dict if decoding, parsing, or validation fails
        return {}

